import{_ as a,o as s,c as e,ae as i}from"./chunks/framework.DK2I2JUh.js";const k=JSON.parse('{"title":"소개","description":"","frontmatter":{"title":"소개"},"headers":[],"relativePath":"ko/guide/introduction.md","filePath":"ko/guide/introduction.md"}'),n={name:"ko/guide/introduction.md"};function o(d,t,r,l,c,h){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="safec-소개" tabindex="-1">SafeC 소개 <a class="header-anchor" href="#safec-소개" aria-label="Permalink to &quot;SafeC 소개&quot;">​</a></h1><p>SafeC는 결정론적이고, 리전을 인식하며, 컴파일 타임을 우선시하는 시스템 프로그래밍 언어입니다. C의 진화형으로서 완전한 C ABI 호환성을 유지하면서도 메모리 안전성, 타입 안전성, 실시간 결정론을 컴파일 타임에, 런타임 오버헤드 없이 강제합니다.</p><h2 id="why-safec" tabindex="-1">왜 SafeC인가? <a class="header-anchor" href="#why-safec" aria-label="Permalink to &quot;왜 SafeC인가? {#why-safec}&quot;">​</a></h2><p>C는 여전히 시스템 프로그래밍의 기반입니다: 운영체제, 임베디드 펌웨어, 오디오 엔진, 네트워크 스택. 하지만 C의 메모리 안전성 부재는 버그, 취약점, 정의되지 않은 동작(UB)의 지속적인 원천입니다.</p><p>기존 대안들은 각각 상당한 트레이드오프를 요구합니다:</p><ul><li>**C++**는 안전 기능을 추가하지만 동시에 숨겨진 비용도 추가합니다: 암묵적 생성자, 소멸자, 예외, RTTI, vtable.</li><li><strong>Rust</strong>는 강력한 안전성 보장을 제공하지만 완전히 새로운 소유권 모델, 새로운 생태계, 그리고 C와 인터페이스하기 위한 만만치 않은 FFI 학습을 요구합니다.</li><li><strong>Zig</strong>는 숨겨진 동작을 제거하지만 리전이 아닌 할당자(allocator)에 기반한 근본적으로 다른 메모리 모델을 사용합니다.</li></ul><p>SafeC는 다른 접근 방식을 취합니다: <strong>C에서 시작하여 숨겨진 비용 없이 안전성을 추가합니다</strong>.</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extern</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> printf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> char*</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> fmt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ...);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 42</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    &amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stack </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ref </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">x;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       // 명시적 리전 표기</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    printf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;x = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%d\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ref);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>C를 알고 있다면 이미 SafeC의 대부분을 아는 것입니다. 추가된 부분들은 명시적이고, 눈에 보이며, 예측 가능합니다.</p><h2 id="core-identity" tabindex="-1">핵심 정체성 <a class="header-anchor" href="#core-identity" aria-label="Permalink to &quot;핵심 정체성 {#core-identity}&quot;">​</a></h2><p>SafeC는 다섯 가지 타협 불가능한 원칙으로 정의됩니다:</p><h3 id="_1-determinism" tabindex="-1">1. 결정론 <a class="header-anchor" href="#_1-determinism" aria-label="Permalink to &quot;1. 결정론 {#_1-determinism}&quot;">​</a></h3><p>동일한 입력은 항상 동일한 출력을 만듭니다. 숨겨진 런타임 변동성도, 비결정론적 동작도 없습니다. 이 덕분에 SafeC는 실시간 시스템, 오디오 처리, 임베디드 펌웨어, 그리고 예측 가능성이 선택 사항이 아닌 모든 영역에 적합합니다.</p><h3 id="_2-zero-hidden-cost" tabindex="-1">2. 숨겨진 비용 없음 <a class="header-anchor" href="#_2-zero-hidden-cost" aria-label="Permalink to &quot;2. 숨겨진 비용 없음 {#_2-zero-hidden-cost}&quot;">​</a></h3><p>모든 연산에는 눈에 보이고 예측 가능한 비용이 있습니다. 암묵적인 힙 할당도, 암묵적인 복사도, 백그라운드 가비지 컬렉션도, 암묵적인 소멸자 체인도 없습니다. 작성한 것이 곧 실행되는 것입니다.</p><h3 id="_3-explicit-control" tabindex="-1">3. 명시적 제어 <a class="header-anchor" href="#_3-explicit-control" aria-label="Permalink to &quot;3. 명시적 제어 {#_3-explicit-control}&quot;">​</a></h3><p>암묵적인 메모리 관리도, 암묵적인 타입 변환도, 암묵적인 에러 처리도 없습니다. 프로그래머가 할당, 라이프타임, 에러 전파를 명시적으로 제어합니다. 컴파일러는 정확성을 검증합니다.</p><h3 id="_4-c-abi-compatibility" tabindex="-1">4. C ABI 호환성 <a class="header-anchor" href="#_4-c-abi-compatibility" aria-label="Permalink to &quot;4. C ABI 호환성 {#_4-c-abi-compatibility}&quot;">​</a></h3><p>SafeC는 기본적으로 C 구조체 레이아웃, C 호출 규약, C 링키지를 사용합니다. SafeC 객체는 C 프로젝트에 직접 링크됩니다. C 헤더는 <code>#include &lt;stdio.h&gt;</code>로 네이티브하게 포함할 수 있습니다.</p><h3 id="_5-compile-time-first-design" tabindex="-1">5. 컴파일 타임 우선 설계 <a class="header-anchor" href="#_5-compile-time-first-design" aria-label="Permalink to &quot;5. 컴파일 타임 우선 설계 {#_5-compile-time-first-design}&quot;">​</a></h3><p>컴파일 타임에 알 수 있는 것은 무엇이든 컴파일 타임에 해결됩니다. <code>consteval</code> 함수는 컴파일 중에 실행됩니다. <code>static_assert</code>는 코드가 실행되기 전에 오류를 잡아냅니다. <code>if const</code>는 컴파일 타임에 분기를 선택합니다. 제네릭은 단형화되어 런타임 디스패치가 없습니다.</p><h2 id="the-determinism-contract" tabindex="-1">결정론 계약 <a class="header-anchor" href="#the-determinism-contract" aria-label="Permalink to &quot;결정론 계약 {#the-determinism-contract}&quot;">​</a></h2><p>SafeC는 숨겨진 런타임 동작이 없음을 보장합니다:</p><ul><li><strong>숨겨진 힙 할당 없음</strong> — 모든 할당은 명시적입니다 (<code>new&lt;R&gt;</code>, <code>malloc</code>)</li><li><strong>숨겨진 런타임 없음</strong> — 런타임 라이브러리가 필요하지 않습니다 (freestanding 모드 사용 가능)</li><li><strong>숨겨진 패닉 없음</strong> — bounds check(경계 검사)를 명시적으로 활성화하지 않는 한 없습니다</li><li><strong>암묵적 예외 없음</strong> — 에러는 던져지지 않고 반환됩니다</li><li><strong>백그라운드 GC 없음</strong> — 메모리는 리전과 명시적 해제를 통해 관리됩니다</li><li><strong>암묵적 소멸자 호출 없음</strong> — 리소스 정리는 명시적입니다 (<code>defer</code>, 수동 free)</li></ul><h2 id="what-safec-adds-to-c" tabindex="-1">SafeC가 C에 추가하는 것 <a class="header-anchor" href="#what-safec-adds-to-c" aria-label="Permalink to &quot;SafeC가 C에 추가하는 것 {#what-safec-adds-to-c}&quot;">​</a></h2><p>SafeC는 C의 실행 모델을 유지하면서 안전성과 현대적 기능을 확장합니다:</p><table tabindex="0"><thead><tr><th>기능</th><th>설명</th></tr></thead><tbody><tr><td><strong>리전</strong></td><td><code>&amp;stack T</code>, <code>&amp;heap T</code>, <code>&amp;arena&lt;R&gt; T</code>, <code>&amp;static T</code>, 또는 <code>&amp;T</code>/<code>?&amp;T</code>(리전 없음) — 컴파일 타임 메모리 안전성</td></tr><tr><td><strong>경계 검사</strong></td><td>정적 및 런타임 배열 경계 검증</td></tr><tr><td><strong>대여 검사</strong></td><td>컴파일 타임에 강제되는 가변/불변 참조 배타성</td></tr><tr><td><strong>제네릭</strong></td><td>단형화를 사용하는 <code>generic&lt;T&gt;</code> — 런타임 비용 없음</td></tr><tr><td><strong>구조체 메서드</strong></td><td>암묵적 <code>self</code> 리시버를 사용하는 <code>Point::length()</code> 구문</td></tr><tr><td><strong>연산자 오버로딩</strong></td><td><code>Vec2 operator+(Vec2 other) const</code></td></tr><tr><td><strong>패턴 매칭</strong></td><td>완전성 검사를 포함한 <code>match</code> 표현식</td></tr><tr><td><strong>옵셔널 타입</strong></td><td><code>?T</code> (암묵적 <code>T -&gt; ?T</code> 래핑), <code>match</code>, <code>.is_null()</code>/<code>.is_none()</code>, 또는 <code>.default(fallback)</code>으로 언래핑</td></tr><tr><td><strong>슬라이스</strong></td><td><code>[]int s = arr[0..3]</code> — 배열에 대한 경계 검사가 이루어진 뷰</td></tr><tr><td><strong>Defer</strong></td><td><code>defer close(fd)</code> — 결정론적 정리</td></tr><tr><td><strong>컴파일 타임 평가</strong></td><td><code>consteval</code>, <code>static_assert</code>, <code>if const</code></td></tr><tr><td><strong>튜플</strong></td><td><code>.0</code>, <code>.1</code> 멤버 접근을 갖는 <code>tuple(int, double)</code></td></tr><tr><td><strong>동시성</strong></td><td><code>spawn</code>/<code>join</code>, 타입이 지정된 채널</td></tr><tr><td><strong>베어메탈 지원</strong></td><td><code>naked</code>, <code>interrupt</code>, <code>asm</code>, <code>--freestanding</code></td></tr></tbody></table><h2 id="what-safec-does-not-add" tabindex="-1">SafeC가 추가하지 않는 것 <a class="header-anchor" href="#what-safec-does-not-add" aria-label="Permalink to &quot;SafeC가 추가하지 않는 것 {#what-safec-does-not-add}&quot;">​</a></h2><p>SafeC가 의도적으로 생략한 것들도 마찬가지로 중요합니다:</p><ul><li>가비지 컬렉터 없음</li><li>예외 없음</li><li>RTTI나 가상 디스패치 없음</li><li>암묵적 생성자나 소멸자 없음</li><li>숨겨진 할당 없음</li><li>표준 런타임 요구사항 없음</li><li>클래스 계층 구조나 상속 없음</li></ul><h2 id="project-components" tabindex="-1">프로젝트 구성 요소 <a class="header-anchor" href="#project-components" aria-label="Permalink to &quot;프로젝트 구성 요소 {#project-components}&quot;">​</a></h2><p>SafeC 프로젝트는 세 가지 주요 구성 요소로 이루어져 있습니다:</p><p><strong>컴파일러 (<code>safec</code>)</strong> — <code>.sc</code> 파일을 LLVM IR로 컴파일하는 완전한 LLVM 프론트엔드입니다. 파이프라인은 다음과 같습니다: 전처리기, 렉서, 파서, AST, Sema(의미 분석), ConstEval(컴파일 타임 평가), CodeGen(LLVM IR 생성).</p><p><strong>표준 라이브러리 (<code>std/</code>)</strong> — 메모리, I/O, 문자열, 수학, 컬렉션, 동시성, 시스템 인터페이스를 다루는 20개 이상의 모듈입니다. 시스템 콜을 위한 C FFI를 포함하여 모두 SafeC로 구현되었습니다.</p><p><strong>패키지 매니저 (<code>safeguard</code>)</strong> — 빌드 도구이자 의존성 관리자입니다. 컴파일, 링킹, 의존성 가져오기, 표준 라이브러리 통합을 처리합니다.</p><h2 id="file-extension" tabindex="-1">파일 확장자 <a class="header-anchor" href="#file-extension" aria-label="Permalink to &quot;파일 확장자 {#file-extension}&quot;">​</a></h2><p>SafeC 소스 파일은 <code>.sc</code> 확장자를 사용합니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hello.sc</span></span>
<span class="line"><span>math_utils.sc</span></span>
<span class="line"><span>audio_engine.sc</span></span></code></pre></div><h2 id="next-steps" tabindex="-1">다음 단계 <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;다음 단계 {#next-steps}&quot;">​</a></h2><ul><li><a href="/safec-docs/ko/guide/getting-started.html">시작하기</a> — 컴파일러를 설치하고 첫 프로그램을 작성합니다</li><li><a href="/safec-docs/ko/guide/design.html">설계 철학</a> — SafeC의 결정 이면에 있는 원칙을 이해합니다</li><li><a href="/safec-docs/ko/guide/comparison.html">비교</a> — SafeC가 C, C++, Rust, Zig와 어떻게 비교되는지 확인합니다</li></ul>`,40)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
